-- Сроки хранения (вторичные), Версия 14 от 20.08.2026. Видны всем ролям; править могут SUPER_ADMIN и DIRECTOR.
create table shelf_life_doc (
    id        smallint primary key check (id = 1),
    title     varchar(200) not null,
    version   integer not null,
    doc_date  date,
    notice    varchar(500)
);
create table shelf_life_zone (
    code       varchar(10) primary key,
    label      varchar(60) not null,
    temp_text  varchar(30) not null,
    sort_order integer not null
);
create table shelf_life_section (
    id         bigserial primary key,
    title      varchar(100) not null,
    note       varchar(500),
    sort_order integer not null
);
create table shelf_life_product (
    id         bigserial primary key,
    section_id bigint not null references shelf_life_section(id) on delete cascade,
    name       varchar(200) not null,
    note       varchar(500),
    sort_order integer not null,
    active     boolean not null default true
);
create table shelf_life_rule (
    id           bigserial primary key,
    product_id   bigint not null references shelf_life_product(id) on delete cascade,
    kind         varchar(10) not null default 'SHELF' check (kind in ('SHELF','THAW','HOLD','WASH','DRY')),
    place        varchar(500) not null,
    term_text    varchar(200) not null,
    duration_min integer,
    zone         varchar(10) references shelf_life_zone(code),
    sort_order   integer not null
);
create index ix_shelf_product_section on shelf_life_product(section_id, sort_order);
create index ix_shelf_rule_product on shelf_life_rule(product_id, sort_order);

  'Таблица действительна, при условии что не поменялась партия продукта. ВСЕГДА СМОТРИТЕ УПАКОВКУ!');

